-- 演示数据均为虚构；在正式环境使用前请替换人员信息和办事规则。
on conflict (id) do update set name=excluded.name, description=excluded.description, sort_order=excluded.sort_order;

on conflict (id) do update set category_id=excluded.category_id, name=excluded.name, role=excluded.role, phone=excluded.phone, email=excluded.email, office=excluded.office, office_hours=excluded.office_hours;

on conflict (id) do update set category_id=excluded.category_id, question=excluded.question, answer=excluded.answer, source_level=excluded.source_level, source_name=excluded.source_name, status=excluded.status;
