insert into categories (id, name, description, sort_order) values
('10000000-0000-4000-8000-000000000001','奖学金助学金','奖学金、助学金、困难认定及资助申请；典型问题：国家奖学金条件、助学金材料、评审时间。',1),
('10000000-0000-4000-8000-000000000002','请假销假','日常请假、病假、返校销假；典型问题：病假材料、请假期限、销假方式。',2),
('10000000-0000-4000-8000-000000000003','证明开具','在读证明、学籍证明及其他学生身份证明；典型问题：在读证明怎么开、证明在哪里领取。',3),
('10000000-0000-4000-8000-000000000004','宿舍与后勤','宿舍报修、宿舍调换、水电和后勤服务；典型问题：宿舍报修、调换宿舍、水电故障。',4),
('10000000-0000-4000-8000-000000000005','校园卡与网络','校园卡挂失补办、余额及校园网络；典型问题：校园卡补办、网络故障、密码重置。',5),
('10000000-0000-4000-8000-000000000006','心理咨询','心理咨询预约、心理支持资源；典型问题：如何预约咨询、咨询是否保密。',6),
('10000000-0000-4000-8000-000000000007','就业实习','就业手续、实习备案与就业指导；典型问题：实习证明、就业协议、招聘会。',7),
('10000000-0000-4000-8000-000000000008','综合事务','其他学生事务、教务协调、考试安排、缓考等；典型问题：缓考怎么申请、考试时间冲突、教务问题找谁。',8)
