insert into knowledge_items (id,category_id,question,answer,source_level,source_name,status) values
('30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000003','在读证明怎么开？','登录学生事务服务平台，进入“证明申请”，选择“在读证明”并提交；审核通过后可在平台下载电子版。',2,'《学生证明办理指南》（演示）','confirmed'),
('30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000003','纸质在读证明在哪里领取？','需要纸质在读证明的同学，可在平台申请时选择纸质版；审核通过后到学生中心服务窗口领取。',1,'证明开具负责老师确认（演示）','confirmed'),
('30000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000002','病假怎么请？','在学生事务服务平台提交病假申请，并上传医疗机构出具的诊断证明；提交后等待辅导员审核。',2,'《学生请假管理办法》（演示）','confirmed'),
('30000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000002','返校后怎么销假？','返校后在学生事务服务平台打开原请假记录，点击“销假”，填写返校时间并提交。',1,'请假负责老师确认（演示）','confirmed'),
('30000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000005','校园卡丢了怎么补办？','先在校园卡服务平台挂失，再携带学生证到校园卡服务窗口申请补办。',2,'《校园卡使用指南》（演示）','confirmed'),
('30000000-0000-4000-8000-000000000006','10000000-0000-4000-8000-000000000005','校园网密码忘了怎么办？','在统一身份认证页面使用“忘记密码”功能重置校园网账号密码。',1,'信息服务老师确认（演示）','confirmed'),
('30000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000004','宿舍设施坏了怎么报修？','打开后勤服务平台的“宿舍报修”，填写楼栋、房间和故障描述后提交报修单。',2,'《后勤报修指南》（演示）','confirmed'),
('30000000-0000-4000-8000-000000000008','10000000-0000-4000-8000-000000000004','宿舍停水停电在哪里反馈？','通过后勤服务平台“水电故障”入口提交楼栋、房间和故障情况。',1,'后勤负责老师确认（演示）','confirmed'),
('30000000-0000-4000-8000-000000000009','10000000-0000-4000-8000-000000000001','国家奖学金申请条件是什么？','申请国家奖学金须为全日制在校二年级及以上学生，上一学年学习成绩和综合测评均位于专业前列；具体排名门槛以当年评审通知为准。',2,'《国家奖学金评审说明》（演示）','confirmed'),
('30000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000001','助学金申请需要先做什么？','申请助学金前，先按当年通知完成家庭经济困难学生认定。',1,'资助负责老师确认（演示）','confirmed'),
('30000000-0000-4000-8000-000000000011','10000000-0000-4000-8000-000000000006','心理咨询怎么预约？','登录心理健康中心预约页面，选择可用时段提交预约；预约成功后按页面提示到心理中心。',2,'《心理咨询预约说明》（演示）','confirmed'),
('30000000-0000-4000-8000-000000000012','10000000-0000-4000-8000-000000000006','心理咨询可以取消预约吗？','可以在预约页面的“我的预约”中取消尚未开始的咨询预约。',1,'心理中心老师确认（演示）','confirmed'),
('30000000-0000-4000-8000-000000000013','10000000-0000-4000-8000-000000000007','校外实习如何备案？','在就业实习服务平台填写实习单位、岗位和起止时间，上传实习接收材料后提交备案。',2,'《学生实习备案指南》（演示）','confirmed'),
('30000000-0000-4000-8000-000000000014','10000000-0000-4000-8000-000000000007','就业协议在哪里下载？','在就业服务平台的“就业协议”栏目下载电子版协议。',1,'就业中心老师确认（演示）','confirmed'),
('30000000-0000-4000-8000-000000000015','10000000-0000-4000-8000-000000000008','考试时间在哪里查看？','登录教务系统，进入“考试安排”查看本人考试科目、时间和地点。',2,'《教务系统使用说明》（演示）','confirmed')
